#
# run_gperf.pl		(c) 2009 Electronic Arts
#
# This script runs gperf.exe on one or more .gperf files and generates
# the appropriate Apt .h/.cpp files.
#
# Note, the C++ code generated by gperf doesn't compile right away 
# with some of the picky compilers we use at EA. So this script takes 
# care of patching the output as needed.
#
# You can run this script on one single .gperf file, or pass it the
# argument --all and it will re-generate everything.
#
# Typically the output filenames (.cpp/.h) have the suffix "Members"
# to indicate that they've been generated by gperf. For example,
# AptSoundMembers.h, AptSpriteMembers.cpp, and so on.
#
# Usage: run_gperf.pl (--all|<filename>)
#
#   --all:    Read all Apt .gperf files.
#   filename: A single .gperf file to read.
#
# Please see the Apt wiki for further detail about Open Source
# license usage: http://docs.ea.com/Apt:User_Guide/Overview#Open_Source_License_Information

use strict;
use FindBin;
use File::Basename;

# path to the source/Apt folder
my $src = "$FindBin::Bin/../../source/Apt";

# path to gperf.exe
my $gperf = "$FindBin::Bin/gperf-2.7.2-bin/bin/gperf.exe";

# if you don't have gperf.exe, there's a script called get_gperf.pl that will
# download it for you.

die "Cannot find '$gperf'. Please run $FindBin::Bin/get_gperf.pl." unless (-e $gperf);

# prints out usage instructions for this script
sub printSyntax()
{
    print "\n";
    print "run_gperf.pl - Generate Apt headers from .gperf files.\n\n";
    print "Usage:  run_gperf.pl (--all|<filename>)\n\n";
    print "--all:\t\tRead all Apt .gperf files.\n";
    print "filename:\tA single .gperf file to read.\n\n";
    print "\n";
    print "Please see the Apt wiki for further detail about Open Source license usage:\n";
    print 'http://docs.ea.com/Apt:User_Guide/Overview#Open_Source_License_Information' . "\n";

}


# list of all .gperf files (without extension)
my @gperf_inputs = (
    'objects',
    'sprite',
    'text',
    'xml',
    'DateMembers',
    'key',
    'util',
    'LoadVarsMembers',
    'MathMembers',
    'sound',
    'StageMembers',
    'StringMembers',
    'TextFormat',
    'ArrayMembers'
);


# arguments passed to gperf for each .gperf file

my %gperf_args = (
    'objects'         => '-t -K szName -E -D -L C++ -Z ObjectIndex -k 1,5,7',
    'sprite'          => '-t -K szName -E -D -L C++ -Z SpriteMembersIndex -k 2,6,8',
    'text'            => '-t -K szName -E -L C++ -Z TextMembersIndex -k 1,2,9',
    'xml'             => '-t -K szName -E -L C++ -Z XmlMemberIndex -k 2,6,8',
    'DateMembers'     => '-t -K szName -E -L C++ -Z DateMembersIndex -D',
    'key'             => '-D -l -t -K szName -E -L C++ -Z KeyMembersIndex -k 2,6,8',
    'util'            => '-D -l -t -K szName -E -L C++ -Z UtilMembersIndex -k 2,6,8',
    'LoadVarsMembers' => '-t -K szName -E -L C++ -Z LoadVarsMembersIndex',
    'MathMembers'     => '-t -K szName -E -L C++ -Z MathMembersIndex -D',
    'sound'           => '-t -K szName -E -L C++ -Z SoundMembersIndex',
    'StageMembers'    => '-D -l -t -K szName -E -L C++ -Z StageMembersIndex -k 2,4,8',
    'StringMembers'   => '-t -K szName -E -L C++ -Z StringMembersIndex -D',
    'TextFormat'      => '-t -K szName -E -L C++ -Z TextFormatMembersIndex -k 1,6,8',
    'ArrayMembers'    => '-t -K szName -E -L C++ -Z ArrayMembersIndex'
);


# output file(s) for each .gperf file

my %gperf_outputs = (
    'objects'         => 'AptObjects.h',
    'sprite'          => 'AptObject/AptSpriteMembers.cpp',
    'text'            => 'AptValue/AptTextMembers.h',
    'xml'             => 'AptObject/AptXmlMembers.cpp',
    'DateMembers'     => 'AptObject/AptDateMembers.h',
    'key'             => 'AptObject/AptKeyMembers.h',
    'util'            => 'AptObject/AptUtilMembers.h',
    'LoadVarsMembers' => 'AptObject/AptLoadVarsMembers.h',
    'MathMembers'     => 'AptObject/AptMathMembers.h',
    'sound'           => 'AptObject/AptSoundMembers.h',
    'StageMembers'    => 'AptObject/AptStageMembers.cpp',
    'StringMembers'   => 'AptValue/AptStringMembers.h',
    'TextFormat'      => 'AptObject/AptTextFormatMembers.h',
    'ArrayMembers'    => 'AptValue/AptArrayMembers.h'
);

# Patches a header file so that it will actually compile.
# Basically, we move a static array named asso_values so 
# that it's defined outside of any function (and we rename it).
# The parameter 'hash_definition_snippet' is supposed to be a fragment of
# the hash()'s definition. That allows this script to find that fragment and
# perform a replacement so that the static array inside of hash()'s definition
# ends up outside of it.
# Example: if for a generated file the hash() function looks like this:
#
#           inline unsigned int
#           UtilMembersIndex::hash (register const char *str, register unsigned int len)
#           {
#               static unsigned char UtilMembersIndex_asso_values[] =
#               {
#                   29, 29, 29, 29, 29, 29, 29, 29, 29, 29,
#                   ...
#               };
#               return len + UtilMembersIndex_asso_values[(unsigned char)str[7]] + UtilMembersIndex_asso_values[(unsigned char)str[5]] + UtilMembersIndex_asso_values[(unsigned char)str[1]];
#           }
#
# then hash_definition_snippet should be '    return len ' so that the script is able to 
# recognize that part and leave it like something like this:
#
#           static unsigned char UtilMembersIndex_asso_values[] =
#           {
#               29, 29, 29, 29, 29, 29, 29, 29, 29, 29,
#               ...
#           };
#           inline unsigned int
#           UtilMembersIndex::hash (register const char *str, register unsigned int len)
#           {
#               return len + UtilMembersIndex_asso_values[(unsigned char)str[7]] + UtilMembersIndex_asso_values[(unsigned char)str[5]] + UtilMembersIndex_asso_values[(unsigned char)str[1]];
#           }
#
# Also activating the guard parameter makes this function surround the header with #ifdef'ed guards.
#
sub processHeaderFile
{
    my $basename = shift;
    my $gperffile = shift;
    my $varname = shift;
    my $hash_definition_snippet = shift;
    my $no_guard = shift;
    my $guard = 1;
    $guard = 0 if defined($no_guard);

    my @outputs = split( ':', $gperf_outputs{ $basename } );
    my $output = "$src/" . @outputs[0];
    my $cmd = $gperf . " " . $gperf_args{ $basename } . " $gperffile > $output";
    $cmd =~ s/\//\\/g;
    return "Failed to run $cmd" if ( system( $cmd ) != 0 );

    open FILE, "$output";
    my $h = join "", <FILE>;
    close FILE;
 
    my $hash_decl = 'inline unsigned int\n' . $varname . '::hash \(register const char \*str, register unsigned int len\)\n{\n';

    $h =~ s/$hash_decl//m;
    $h =~ s/$hash_definition_snippet/\ninline unsigned int\n${varname}::hash \(register const char \*str, register unsigned int len\)\n{\n$hash_definition_snippet/m;
    $h =~ s/asso_values\[/${varname}_asso_values\[/gm;

    open FILE, ">$output";
    
    print FILE "#ifndef _apt_gperf_generated_" . $basename . "_h\n"         if ( $guard );
    print FILE "#define _apt_gperf_generated_" . $basename . "_h\n\n"       if ( $guard );
    print FILE "// Please see the Apt wiki for further detail about Open Source license usage:\n";
    print FILE '// http://docs.ea.com/Apt:User_Guide/Overview#Open_Source_License_Information' . "\n\n";
    
    print FILE $h;
    
    print FILE "#endif    // _apt_gperf_generated_" . $basename . "_h\n"    if ( $guard );
    close FILE;
    return '';
}

# A few of the .gperf files generate .cpp files instead of .h files.
# They are xml.gperf, StageMembers.gperf and sprite.gperf.
# We use this slightly convoluted function to patch the generated .cpp
# file so that it #includes _Apt.h and basically behaves like what we want.
# (please see note in processHeaderFile for parameters description)
sub processCppFile
{
    my $basename = shift;
    my $gperffile = shift;
    my $varname = shift;
    my $hash_definition_snippet = shift;
    my $structname = shift;
    my $macroname = shift;
    my $headerfile = shift;

    my @outputs = split( ':', $gperf_outputs{ $basename } );
    my $output = "$src/" . @outputs[0];
    my $err = processHeaderFile $basename, $gperffile, $varname, $hash_definition_snippet, 1;
    die $err if ( $err != '' );

    open FILE, "$output";
    my $h = join "", <FILE>;
    close FILE;

    my $class_decl = 'struct ' . $structname . ' { char \*szName; int nIndex; };';
    $h =~ s/$class_decl//m;

    $class_decl = 'class ' . $varname . '\n{\nprivate:\n  static inline unsigned int hash \(const char \*str, unsigned int len\);\npublic:\n  static struct ' . $structname . ' \*in_word_set \(const char \*str, unsigned int len\);\n};\n\n';
    $h =~ s/$class_decl//m;

    open FILE, ">$output";
    print FILE '#include "_Apt.h"' . "\n";
    print FILE '#if defined (' . $macroname . ')' . "\n" if ($macroname ne '');
    print FILE '#include "' . $headerfile . "\"\n";
    print FILE '#include "MainInline.h"' . "\n\n";
    print FILE $h;
    print FILE '#endif      //' . $macroname . "\n" if ($macroname ne '');
    close FILE;
    return '';
}


#
# these functions are called by processFiles() in order to handle each .gperf file
#

sub process_objects
{
    return processHeaderFile "objects", "$src/objects.gperf", "ObjectIndex", "  register int hval = len;\n";
}

sub process_text
{
    return processHeaderFile "text", "$src/text.gperf", "TextMembersIndex", "  register int hval = len;\n";
}

sub process_DateMembers
{
    return processHeaderFile "DateMembers", "$src/AptObject/DateMembers.gperf", "DateMembersIndex", "  return len ";
}

sub process_key
{
    return processHeaderFile "key", "$src/AptObject/key.gperf", "KeyMembersIndex", "  register int hval = len;\n";
}

sub process_util
{
    return processHeaderFile "util", "$src/AptObject/util.gperf", "UtilMembersIndex", "  return len ";
}

sub process_LoadVarsMembers
{
    return processHeaderFile "LoadVarsMembers", "$src/AptObject/LoadVarsMembers.gperf", "LoadVarsMembersIndex", "  return len ";
}

sub process_MathMembers
{
    return processHeaderFile "MathMembers", "$src/AptObject/MathMembers.gperf", "MathMembersIndex", "  return len ";
}

sub process_sound
{
    return processHeaderFile "sound", "$src/AptObject/sound.gperf", "SoundMembersIndex", "  return len ";
}

sub process_StringMembers
{ 
    return processHeaderFile "StringMembers", "$src/AptObject/StringMembers.gperf", "StringMembersIndex", "  return len ";
}

sub process_TextFormat
{
    return processHeaderFile "TextFormat", "$src/AptObject/TextFormat.gperf", "TextFormatMembersIndex", "  register int hval = len;\n";
}

sub process_ArrayMembers
{
    return processHeaderFile "ArrayMembers", "$src/AptValue/ArrayMembers.gperf", "ArrayMembersIndex", "  return len ";
}

sub process_xml
{
    return processCppFile "xml", "$src/xml.gperf", "XmlMemberIndex", "  register int hval = len;\n", "XmlMembers", "APT_USE_XML_OBJECT", 'AptXmlMembers.h';
}

sub process_StageMembers
{
    return processCppFile "StageMembers", "$src/AptObject/StageMembers.gperf", "StageMembersIndex", "  register int hval = len;\n", "StageMembers", "APT_USE_STAGE_OBJECT", 'AptStageMembers.h';
}

sub process_sprite
{
    return processCppFile "sprite", "$src/sprite.gperf", "SpriteMembersIndex", "  register int hval = len;\n", "SpriteMembers", '', 'AptSpriteMembers.h';
}

#
# processFile takes a .gperf file as an argument and causes
# one of the process_xxxx functions to be called. When this
# function is complete, a .h (or .cpp) file has been generated.
#
sub processFile
{
    my $inputBaseName = shift;
    print "Processing $inputBaseName... ";

    my @outputs = split( ':', $gperf_outputs{ $inputBaseName } );
    foreach my $output (@outputs)
    {
        $output = "$src/$output";
        die "'$output' doesn't exist yet" unless (-e $output);
        die "'$output' is readonly" unless (-w $output);
        print "Output file is: $output.\n";
    }

    my $err = '';
    eval "\$err = process_$inputBaseName();";
    print "ERROR: $err" if ($err ne '');
}

# --------------------------------
#
# Script starting point
#
# --------------------------------

my $arg = shift;

unless (defined($arg))
{
    printSyntax();
    exit 1;
}

my $filename;

if ($arg ne "--all")
{
    $filename = $arg;
}

if (defined($filename))
{
    #
    # run on a single .gperf file
    #

    die "Cannot find .gperf file '$filename'" unless (-e $filename); 
    my $basename = basename($filename, '.gperf');
    processFile $basename;
}
else
{
    #
    # run on all .gperf files
    #

    foreach my $basename (@gperf_inputs)
    {
        processFile $basename;
    }
}

